```python
from itertools import permutations

# Define the problem
people = ['Blake', 'Finley', 'Quinn', 'Riley', 'Sawyer']
colors = ['blue', 'orange', 'red', 'white', 'yellow']
pets = ['cat', 'dog', 'fish', 'horse', 'rabbit']
drinks = ['cocoa', 'coffee', 'juice', 'milk', 'water']
hobbies = ['chess', 'fencing', 'hiking', 'painting', 'rowing']

def check_constraints(assignment):
    """
    assignment is a dict: person -> (pos, color, pet, drink, hobby)
    where pos is 1-5
    """

    # Helper function to get person/attribute at a position
    def get_at_pos(pos, attr_type):
        for person, (p, color, pet, drink, hobby) in assignment.items():
            if p == pos:
                if attr_type == 'color': return color
                elif attr_type == 'pet': return pet
                elif attr_type == 'drink': return drink
                elif attr_type == 'hobby': return hobby
                elif attr_type == 'person': return person
        return None

    def person_at_pos(pos):
        return get_at_pos(pos, 'person')

    def pos_of_person(person):
        return assignment[person][0]

    def pos_with_drink(drink):
        for person, (p, _, _, d, _) in assignment.items():
            if d == drink: return p
        return None

    def pos_with_pet(pet):
        for person, (p, _, pet_v, _, _) in assignment.items():
            if pet_v == pet: return p
        return None

    def pos_with_color(color):
        for person, (p, col, _, _, _) in assignment.items():
            if col == color: return p
        return None

    def pos_with_hobby(hobby):
        for person, (p, _, _, _, h) in assignment.items():
            if h == hobby: return p
        return None

    # Check all constraints

    # 1. Coffee drinker lives next to blue house
    coffee_pos = pos_with_drink('cocoa')
    if coffee_pos is None: return False
    blue_pos = pos_with_color('blue')
    if blue_pos is None: return False
    if abs(coffee_pos - blue_pos) != 1:
        # We're actually looking for 'coffee', not 'cocoa'
        pass

    # Let me rewrite this more carefully
    checks_passed = True

    # 1. Coffee drinker lives next to blue house
    coffee_pos = pos_with_drink('coffee')
    blue_pos = pos_with_color('blue')
    if coffee_pos and blue_pos and abs(coffee_pos - blue_pos) != 1:
        return False

    # 2. Fencing immediately left of fish owner
    fencing_pos = pos_with_hobby('fencing')
    fish_pos = pos_with_pet('fish')
    if fencing_pos and fish_pos and fencing_pos + 1 != fish_pos:
        return False

    # 3. Hiking immediately left of Sawyer
    hiking_pos = pos_with_hobby('hiking')
    sawyer_pos = pos_of_person('Sawyer')
    if hiking_pos and sawyer_pos and hiking_pos + 1 != sawyer_pos:
        return False

    # 4. Juice drinker is dog owner
    juice_pos = pos_with_drink('juice')
    dog_pos = pos_with_pet('dog')
    if juice_pos and dog_pos and juice_pos != dog_pos:
        return False

    # 5. Orange house person drinks water
    orange_pos = pos_with_color('orange')
    water_pos = pos_with_drink('water')
    if orange_pos and water_pos and orange_pos != water_pos:
        return False

    # 6. Juice drinker not in white house
    white_pos = pos_with_color('white')
    if juice_pos and white_pos and juice_pos == white_pos:
        return False

    # 7. Horse owner lives next to Quinn
    horse_pos = pos_with_pet('horse')
    quinn_pos = pos_of_person('Quinn')
    if horse_pos and quinn_pos and abs(horse_pos - quinn_pos) != 1:
        return False

    # 8. Cocoa drinker immediately left of red house
    cocoa_pos = pos_with_drink('cocoa')
    red_pos = pos_with_color('red')
    if cocoa_pos and red_pos and cocoa_pos + 1 != red_pos:
        return False

    # 9. White house lives next to fish owner
    if white_pos and fish_pos and abs(white_pos - fish_pos) != 1:
        return False

    # 10. Blake immediately left of red house
    blake_pos = pos_of_person('Blake')
    if blake_pos and red_pos and blake_pos + 1 != red_pos:
        return False

    # 11. Milk drinker immediately left of rabbit owner
    milk_pos = pos_with_drink('milk')
    rabbit_pos = pos_with_pet('rabbit')
    if milk_pos and rabbit_pos and milk_pos + 1 != rabbit_pos:
        return False

    # 12. Sawyer lives next to white house
    if sawyer_pos and white_pos and abs(sawyer_pos - white_pos) != 1:
        return False

    # 13. Finley not in orange house
    finley_pos = pos_of_person('Finley')
    if finley_pos and orange_pos and finley_pos == orange_pos:
        return False

    # 14. Painting hobby is fish owner
    painting_pos = pos_with_hobby('painting')
    if painting_pos and fish_pos and painting_pos != fish_pos:
        return False

    # 15. Water drinker is rabbit owner
    if water_pos and rabbit_pos and water_pos != rabbit_pos:
        return False

    # 16. Chess hobby is not Finley
    chess_pos = pos_with_hobby('chess')
    if chess_pos and finley_pos and chess_pos == finley_pos:
        return False

    # 17. Riley immediately left of rowing hobby
    riley_pos = pos_of_person('Riley')
    rowing_pos = pos_with_hobby('rowing')
    if riley_pos and rowing_pos and riley_pos + 1 != rowing_pos:
        return False

    return True

# Try all permutations
solutions = []

for person_perm in permutations(people):
    for color_perm in permutations(colors):
        for pet_perm in permutations(pets):
            for drink_perm in permutations(drinks):
                for hobby_perm in permutations(hobbies):
                    assignment = {}
                    for i in range(5):
                        assignment[person_perm[i]] = (i+1, color_perm[i], pet_perm[i], drink_perm[i], hobby_perm[i])

                    if check_constraints(assignment):
                        solutions.append(assignment)

# Print the solution
if solutions:
    sol = solutions[0]
    print("Solution found:")
    for pos in range(1, 6):
        for person, (p, color, pet, drink, hobby) in sol.items():
            if p == pos:
                print(f"Position {pos}: {person}, {color} house, {pet}, {drink}, {hobby}")

    # Find rabbit owner
    for person, (p, color, pet, drink, hobby) in sol.items():
        if pet == 'rabbit':
            print(f"\nRabbit owner: {person}")
else:
    print("No solution found")
